```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define FILENAME "data.csv"

int main(int argc, char *argv[]) {
    // read from file
	FILE *fp = fopen(FILENAME, "r");
	char *str = malloc(sizeof(char) * 100);
	fread(str, sizeof(char), strlen(str), fp);
	fclose(fp);

    // convert to float
	char *token = strtok(str, ",");
	float a = atof(token);
	token = strtok(NULL, ",");
	float b = atof(token);
	token = strtok(NULL, ",");
	float c = atof(token);

    // print result
	printf("%f %f %f\n", a, b, c);

    // free memory
	free(str);

    return 0;
}
```

